window.DATA={"meta":{"title":"L'ultima festa di Vic Lombardo","subtitle":"Cena con delitto · Long Island, 1926","kicker":"Long Island · 1926","icon":"🥂","host":"vic","voices":{"n":"","v":"Vic Lombardo","a":"Ambrogio"}},"pub":{"tony":{"name":"Tony","g":"m","img":"img/p-tony.jpg","partner":"noemi","title":"L'Impresario del Gatto Nero","costume":"Gessato, cappello fedora, maschera dorata, sigaro","dress":"un completo scuro (meglio gessato), un cappello e, se ce l'hai, un sigaro finto 🎩","blurb":"Padrone del Gatto Nero, il locale clandestino più caldo di Manhattan. Parla di sé in terza persona e non stacca mai dal telefono: a ogni festa si fa passare New York da Ambrogio. Fuma solo sigari cubani. Il gin del suo locale lo compra da Vic… a credito."},"noemi":{"name":"Noemi","g":"f","img":"img/p-noemi.jpg","partner":"tony","title":"La Regina del Charleston","costume":"Abito a frange nero e oro, fascia con piuma, braccialetti, vassoio delle sigarette","dress":"un vestito con le frange o luccicante, una fascia tra i capelli e tanti braccialetti 💃","blurb":"Gira tra gli ospiti con il vassoio delle sigarette al collo e balla il charleston meglio di chiunque. Bellissima e monella: chi le compra una sigaretta le racconta un segreto. Le sigarette le vende, ma non le fuma. Vic ha un debole per lei, e non lo nasconde."},"francesca":{"name":"Francesca","g":"f","img":"img/p-francesca.jpg","partner":"simone","title":"Madame Sole e Luna","costume":"Turbante con sole e luna, scialle con monetine, trucco metà oro e metà argento","dress":"un foulard a turbante, uno scialle e, se ti va, un trucco metà oro e metà argento 🌗","blurb":"Medium. Ogni venerdì guida le sedute spiritiche di Vic, che vuole parlare con la madre morta in Sicilia. Il suo umore cambia come la luna: o è raggiante, o è nera come la notte. E quando si lamenta… si lamenta con Simone."},"simone":{"name":"Simone","g":"m","img":"img/p-simone.jpg","partner":"francesca","title":"Il Semidio","costume":"Berretto e giacca da autista, maschera nera da domino, guantoni da boxe","dress":"una camicia bianca con le bretelle o una coppola, e una mascherina nera 🥊","blurb":"Ex campione dei pesi massimi, oggi autista di Vic: guida la Rolls-Royce e custodisce i fuochi d'artificio. Fortissimo, ma appena si siede si addormenta. Non fuma: «fa male al fiato»."},"lorenzo":{"name":"Lorenzo","g":"m","img":"img/p-lorenzo.jpg","partner":"claudia","title":"Il Ragioniere","costume":"Gilet, occhiali tondi, maschera nera da domino, registro dei conti","dress":"un gilet o le bretelle, occhiali tondi se li hai e una mascherina nera 🕶️","blurb":"Il braccio destro di Tony: tiene i conti del Gatto Nero e la sera studia Legge. Tony parla, Lorenzo fa. Parla poco e ricorda ogni numero."},"claudia":{"name":"Claudia","g":"f","img":"img/p-claudia.jpg","partner":"lorenzo","title":"La Gatta Nera","costume":"Abito di velluto nero, orecchie da gatta, baffi disegnati, bocchino","dress":"qualcosa di nero e due baffi da gatta disegnati 🐈‍⬛","blurb":"Studentessa di psicoanalisi, allieva di un famoso dottore di Vienna. Da tre mesi, ogni martedì, ascolta gli incubi di Vic. Fuma sigarette turche col bocchino e legge le persone come libri aperti."}},"npc":{"vic":{"name":"Vic Lombardo","img":"img/n-vic.jpg","blurb":"61 anni, il Re del Gin. Partito da Lentini a 14 anni con una valigia di cartone, oggi è l'uomo più ricco della costa. Generoso, malinconico, vendicativo. Non fuma da vent'anni e non sopporta il fumo."},"ambrogio":{"name":"Ambrogio","img":"img/n-ambrogio.jpg","blurb":"Il maggiordomo. 70 anni, siciliano, da trent'anni con Vic. In guerra faceva l'infermiere. Senza occhiali non vede a un metro."}},"facts":["21:00 — Cena e ballo in maschera. Vic: «A mezzanotte, a luci spente, farò un annuncio che cambierà la vita di tutti voi».","23:15 — Vic sale nello studio della torre. Ambrogio gli porta gin, un secchiello di ghiaccio e il punteruolo.","23:15–23:58 — La festa continua: maschere, charleston, gente che va e viene.","23:58 — Ambrogio spegne tutte le luci della villa per i fuochi d'artificio.","00:00 — Fuochi sul mare. Dalla torre si sente uno sparo.","00:06 — Torna la luce. 00:10 — Ambrogio trova Vic morto."],"vote":{"suspects":["tony","noemi","francesca","simone","lorenzo","claudia","ambrogio"],"questions":[{"id":"killer","q":"Chi ha ucciso Vic Lombardo?","pts":3},{"id":"book","q":"Chi ha rubato il libro nero?","pts":1},{"id":"gun","q":"Chi ha nascosto la pistola nel pianoforte?","pts":1},{"id":"actor","q":"Miglior attore/attrice della serata (non tu)","pts":0,"players":true}]},"topic":"ufv-myk09qafciza","scene":{"villa":"img/s-villa.jpg","cena":"img/s-cena.jpg"},"p":{"0c763c868e614f9b":"","6a4b5e53484ed3fc":"","ad24df94c1a2d576":"","66fdc398a5cfe489":"","e20e43a0ef4cfa22":"","9d6444758436c653":""},"h":{"f0e5767fa8b09519":""},"v":1793485295216};
